/// One implementation of every method, shared by the binary and the
/// JSON-RPC endpoints.
pub trait Service: Sync {
    /// Protocol and build identity.
    fn daemon_version(
        &self,
        params: Empty,
    ) -> impl ::core::future::Future<Output = Result<VersionInfo, RpcError>> + Send;
    /// Process, socket, log, and tmux endpoint state.
    fn daemon_status(
        &self,
        params: Empty,
    ) -> impl ::core::future::Future<Output = Result<DaemonStatus, RpcError>> + Send;
    /// Stop the daemon; tmux sessions and panes keep running.
    fn daemon_shutdown(
        &self,
        params: Empty,
    ) -> impl ::core::future::Future<Output = Result<ShutdownResult, RpcError>> + Send;
    /// Sessions, windows, and panes of one endpoint.
    fn tmux_topology(
        &self,
        params: TopologyParams,
    ) -> impl ::core::future::Future<Output = Result<Topology, RpcError>> + Send;
    /// Size a tmux window for the client that owns its size (see SizeWindow).
    fn tmux_size_window(
        &self,
        params: SizeWindow,
    ) -> impl ::core::future::Future<Output = Result<SizeResult, RpcError>> + Send;
    /// A tmux paste buffer's text: the newest, or one a clipboard.tmux_buffer event named.
    fn clipboard_read_tmux_buffer(
        &self,
        params: TmuxBufferRead,
    ) -> impl ::core::future::Future<Output = Result<TmuxBuffer, RpcError>> + Send;
    /// Make text tmux's newest paste buffer, for tmux's own paste and other tmux clients. Not reported back as a clipboard.tmux_buffer event.
    fn clipboard_write_tmux_buffer(
        &self,
        params: TmuxBufferWrite,
    ) -> impl ::core::future::Future<Output = Result<Empty, RpcError>> + Send;
    /// The current topology; afterwards `tmux.topology` events follow every change.
    fn tmux_watch(
        &self,
        params: TopologyParams,
    ) -> impl ::core::future::Future<Output = Result<TopologyUpdate, RpcError>> + Send;
    /// Run a typed action and report its observed outcome.
    fn actions_submit(
        &self,
        params: SubmitAction,
    ) -> impl ::core::future::Future<Output = Result<ActionRecord, RpcError>> + Send;
    /// Hold a pane's interaction lease, so automated input to it is accepted until a person types there.
    fn leases_acquire(
        &self,
        params: LeaseAcquire,
    ) -> impl ::core::future::Future<Output = Result<Lease, RpcError>> + Send;
    fn leases_release(
        &self,
        params: LeaseRef,
    ) -> impl ::core::future::Future<Output = Result<Empty, RpcError>> + Send;
    fn actions_get(
        &self,
        params: ActionQuery,
    ) -> impl ::core::future::Future<Output = Result<ActionRecord, RpcError>> + Send;
    fn actions_list(
        &self,
        params: ActionListParams,
    ) -> impl ::core::future::Future<Output = Result<ActionList, RpcError>> + Send;
    /// Bounded text, cursor, and size from a pane's canonical mirror.
    fn terminal_read(
        &self,
        params: ReadParams,
    ) -> impl ::core::future::Future<Output = Result<TerminalText, RpcError>> + Send;
    /// Every mirrored pane and its state.
    fn terminal_mirrors(
        &self,
        params: TopologyParams,
    ) -> impl ::core::future::Future<Output = Result<MirrorList, RpcError>> + Send;
    /// Mark a mirrored pane Hot or Warm.
    fn terminal_set_tier(
        &self,
        params: SetTier,
    ) -> impl ::core::future::Future<Output = Result<Empty, RpcError>> + Send;
    /// Follow a pane's canonical mirror: checkpoint or replay, then ordered records.
    fn terminal_subscribe(
        &self,
        params: TerminalSubscribe,
    ) -> impl ::core::future::Future<Output = Result<Subscription, RpcError>> + Send;
    fn terminal_unsubscribe(
        &self,
        params: Unsubscribe,
    ) -> impl ::core::future::Future<Output = Result<Empty, RpcError>> + Send;
    /// Keys, text, paste, focus, or mouse for a pane, encoded against its canonical state.
    fn terminal_input(
        &self,
        params: TerminalInput,
    ) -> impl ::core::future::Future<Output = Result<InputResult, RpcError>> + Send;
    /// Connect to another host's daemon over ssh; the connection belongs to this daemon, not the caller. With no destination, `name` is a profile from hosts.yaml.
    fn hosts_connect(
        &self,
        params: HostConnect,
    ) -> impl ::core::future::Future<Output = Result<HostStatus, RpcError>> + Send;
    /// Every remote host this daemon knows and its state.
    fn hosts_list(
        &self,
        params: Empty,
    ) -> impl ::core::future::Future<Output = Result<HostList, RpcError>> + Send;
    /// Close a host's ssh connection. The remote daemon and its tmux keep running.
    fn hosts_disconnect(
        &self,
        params: HostRef,
    ) -> impl ::core::future::Future<Output = Result<HostStatus, RpcError>> + Send;
    /// Connect again now, also after a failure that is not retried automatically.
    fn hosts_reconnect(
        &self,
        params: HostRef,
    ) -> impl ::core::future::Future<Output = Result<HostStatus, RpcError>> + Send;
    /// Follow a pane on a connected host; resumes from the host's journal after SSH loss. End it with terminal.unsubscribe.
    fn hosts_subscribe(
        &self,
        params: HostSubscribe,
    ) -> impl ::core::future::Future<Output = Result<Subscription, RpcError>> + Send;
    /// A host's topology; afterwards `tmux.topology` events follow every change, across reconnects. One watch (local or a host) per connection.
    fn hosts_watch(
        &self,
        params: HostRef,
    ) -> impl ::core::future::Future<Output = Result<TopologyUpdate, RpcError>> + Send;
    /// Probe a host over SSH and say what installing this daemon's server version there would do.
    fn hosts_install_plan(
        &self,
        params: InstallPlanParams,
    ) -> impl ::core::future::Future<Output = Result<InstallPlan, RpcError>> + Send;
    /// Install the reviewed plan: stream the archive, verify its SHA-256 on the host, unpack into a versioned directory, switch atomically.
    fn hosts_install(
        &self,
        params: InstallParams,
    ) -> impl ::core::future::Future<Output = Result<InstallResult, RpcError>> + Send;
    /// Install the reviewed plan, restart the host's daemon on it (tmux keeps running), and reconnect.
    fn hosts_upgrade(
        &self,
        params: UpgradeParams,
    ) -> impl ::core::future::Future<Output = Result<UpgradeResult, RpcError>> + Send;
    /// Forward one typed call to a connected host's daemon.
    fn hosts_call(
        &self,
        params: HostCall,
    ) -> impl ::core::future::Future<Output = Result<HostReply, RpcError>> + Send;
    /// Give up authority on this connection: the new grant must be within the current one. Nothing widens a grant.
    fn grants_narrow(
        &self,
        params: Grant,
    ) -> impl ::core::future::Future<Output = Result<Grant, RpcError>> + Send;
    /// The calling connection's own grant.
    fn grants_current(
        &self,
        params: Empty,
    ) -> impl ::core::future::Future<Output = Result<Grant, RpcError>> + Send;
    /// Start a program in a new tmux window with a single-use registration ticket (owner only).
    fn apps_launch(
        &self,
        params: LaunchApp,
    ) -> impl ::core::future::Future<Output = Result<LaunchedApp, RpcError>> + Send;
    /// Follow the daemon's event log: `events.batch` events follow, with a gap whenever events were skipped.
    fn events_subscribe(
        &self,
        params: EventSubscribe,
    ) -> impl ::core::future::Future<Output = Result<EventSubscription, RpcError>> + Send;
    fn events_unsubscribe(
        &self,
        params: Unsubscribe,
    ) -> impl ::core::future::Future<Output = Result<Empty, RpcError>> + Send;
    /// Send a topic or direct message; the daemon stamps the sender. Never typed into a pane.
    fn messages_publish(
        &self,
        params: MessagePublish,
    ) -> impl ::core::future::Future<Output = Result<MessageSent, RpcError>> + Send;
    /// Send a request to one instance and wait for its reply.
    fn messages_request(
        &self,
        params: MessageRequest,
    ) -> impl ::core::future::Future<Output = Result<MessageEnvelope, RpcError>> + Send;
    /// Answer a request sent to this connection.
    fn messages_reply(
        &self,
        params: MessageReply,
    ) -> impl ::core::future::Future<Output = Result<MessageSent, RpcError>> + Send;
    /// Receive messages: `messages.deliver` events follow.
    fn messages_subscribe(
        &self,
        params: MessageSubscribe,
    ) -> impl ::core::future::Future<Output = Result<MessageSubscription, RpcError>> + Send;
    fn messages_unsubscribe(
        &self,
        params: Unsubscribe,
    ) -> impl ::core::future::Future<Output = Result<Empty, RpcError>> + Send;
    /// Supervised extensions and their state.
    fn extensions_list(
        &self,
        params: Empty,
    ) -> impl ::core::future::Future<Output = Result<ExtensionList, RpcError>> + Send;
    /// Stop an extension if it runs and start it now, also one parked as failed (owner only).
    fn extensions_restart(
        &self,
        params: ExtensionRef,
    ) -> impl ::core::future::Future<Output = Result<ExtensionStatus, RpcError>> + Send;
    /// Compile a script without running it.
    fn scripts_validate(
        &self,
        params: ScriptSource,
    ) -> impl ::core::future::Future<Output = Result<ScriptCheck, RpcError>> + Send;
    /// Run a script in its own sandboxed VM with the given grant until it is stopped or the daemon stops (owner only).
    fn scripts_load(
        &self,
        params: ScriptLoad,
    ) -> impl ::core::future::Future<Output = Result<ScriptStatus, RpcError>> + Send;
    /// Replace a script's source atomically; an update that does not load leaves the last-good version running (owner only).
    fn scripts_reload(
        &self,
        params: ScriptSource,
    ) -> impl ::core::future::Future<Output = Result<ScriptStatus, RpcError>> + Send;
    /// Stop and unload a script (owner only).
    fn scripts_stop(
        &self,
        params: ScriptRef,
    ) -> impl ::core::future::Future<Output = Result<ScriptStatus, RpcError>> + Send;
    fn scripts_list(
        &self,
        params: Empty,
    ) -> impl ::core::future::Future<Output = Result<ScriptList, RpcError>> + Send;
    /// Search the newest lines of many panes, here and on connected hosts, within fixed bounds.
    fn terminal_query(
        &self,
        params: TerminalQuery,
    ) -> impl ::core::future::Future<Output = Result<QueryResult, RpcError>> + Send;
    /// A pane's valid decorations; a decorations.changed event says when to list again.
    fn decorations_list(
        &self,
        params: DecorationQuery,
    ) -> impl ::core::future::Future<Output = Result<DecorationList, RpcError>> + Send;
    /// Start a filter: a text tap, the Rust match stage, and its outputs, under its own grant (owner only).
    fn filters_install(
        &self,
        params: FilterSpec,
    ) -> impl ::core::future::Future<Output = Result<FilterStatus, RpcError>> + Send;
    fn filters_list(
        &self,
        params: Empty,
    ) -> impl ::core::future::Future<Output = Result<FilterList, RpcError>> + Send;
    /// (owner only)
    fn filters_pause(
        &self,
        params: FilterRef,
    ) -> impl ::core::future::Future<Output = Result<FilterStatus, RpcError>> + Send;
    /// Resume a paused or tripped filter (owner only).
    fn filters_resume(
        &self,
        params: FilterRef,
    ) -> impl ::core::future::Future<Output = Result<FilterStatus, RpcError>> + Send;
    /// (owner only)
    fn filters_remove(
        &self,
        params: FilterRef,
    ) -> impl ::core::future::Future<Output = Result<FilterStatus, RpcError>> + Send;
    /// Run an exact program in its own tmux window through the job wrapper; it keeps running if the daemon stops.
    fn jobs_start(
        &self,
        params: JobStart,
    ) -> impl ::core::future::Future<Output = Result<JobRecord, RpcError>> + Send;
    fn jobs_get(
        &self,
        params: JobRef,
    ) -> impl ::core::future::Future<Output = Result<JobRecord, RpcError>> + Send;
    fn jobs_list(
        &self,
        params: Empty,
    ) -> impl ::core::future::Future<Output = Result<JobList, RpcError>> + Send;
    /// Send SIGTERM to the job's program; its record says killed once it ends.
    fn jobs_cancel(
        &self,
        params: JobRef,
    ) -> impl ::core::future::Future<Output = Result<JobRecord, RpcError>> + Send;
    /// The files the job left in its artifacts directory.
    fn jobs_artifacts(
        &self,
        params: JobRef,
    ) -> impl ::core::future::Future<Output = Result<JobArtifacts, RpcError>> + Send;
    /// The user's processes on this host, with their panes and agent runs, by evidence.
    fn processes_list(
        &self,
        params: ProcessQuery,
    ) -> impl ::core::future::Future<Output = Result<ProcessList, RpcError>> + Send;
    /// A provider hook's report about its session (sent by dream hook).
    fn agents_event(
        &self,
        params: AgentEvent,
    ) -> impl ::core::future::Future<Output = Result<Empty, RpcError>> + Send;
    /// Agent runs (Claude Code, Codex) here and on connected hosts, from the process registry.
    fn agents_runs(
        &self,
        params: AgentRunQuery,
    ) -> impl ::core::future::Future<Output = Result<AgentRunList, RpcError>> + Send;
    /// Follow panes at one level; `taps.data` events follow. A tap never slows the panes it reads: one that falls behind gets a gap.
    fn taps_subscribe(
        &self,
        params: TapSubscribe,
    ) -> impl ::core::future::Future<Output = Result<TapSubscription, RpcError>> + Send;
    fn taps_unsubscribe(
        &self,
        params: Unsubscribe,
    ) -> impl ::core::future::Future<Output = Result<Empty, RpcError>> + Send;
    /// Trade a launch ticket for the app's narrow grant on this connection.
    fn apps_register(
        &self,
        params: RegisterApp,
    ) -> impl ::core::future::Future<Output = Result<Registration, RpcError>> + Send;
    /// Every pane in scope with its session, window, command, directory, title, size, tier, and activity.
    fn terminal_list(
        &self,
        params: TopologyParams,
    ) -> impl ::core::future::Future<Output = Result<TerminalList, RpcError>> + Send;
    /// Wait until a pattern appears in a pane, it goes quiet, or its program ends; bounded by a timeout.
    fn terminal_watch(
        &self,
        params: TerminalWatch,
    ) -> impl ::core::future::Future<Output = Result<WatchResult, RpcError>> + Send;
    /// Run an exact program as a job in a new window or pane the caller then owns; returns its exit status and output.
    fn terminal_run(
        &self,
        params: TerminalRun,
    ) -> impl ::core::future::Future<Output = Result<RunResult, RpcError>> + Send;
    /// Actions waiting for the user's approval (owner only).
    fn approvals_list(
        &self,
        params: Empty,
    ) -> impl ::core::future::Future<Output = Result<ApprovalList, RpcError>> + Send;
    /// Allow or deny a waiting action (owner only).
    fn approvals_answer(
        &self,
        params: ApprovalAnswer,
    ) -> impl ::core::future::Future<Output = Result<Approval, RpcError>> + Send;
    /// Start a collector: a standing rule that records rows from pane output. It only reads, and survives daemon restarts.
    fn collect_create(
        &self,
        params: CollectorSpec,
    ) -> impl ::core::future::Future<Output = Result<CollectorStatus, RpcError>> + Send;
    fn collect_list(
        &self,
        params: Empty,
    ) -> impl ::core::future::Future<Output = Result<CollectList, RpcError>> + Send;
    /// A collector's rows, filtered, or counts grouped by a field.
    fn collect_query(
        &self,
        params: CollectQuery,
    ) -> impl ::core::future::Future<Output = Result<CollectResult, RpcError>> + Send;
    /// Stop a collector; its rows stay queryable unless delete is set.
    fn collect_stop(
        &self,
        params: CollectRef,
    ) -> impl ::core::future::Future<Output = Result<CollectorStatus, RpcError>> + Send;
    /// Show, focus, hide, or restart a tmux session's harness drawer: a pane running the configured agent harness, kept in a holding session while hidden (owner only).
    fn drawer_toggle(
        &self,
        params: DrawerRequest,
    ) -> impl ::core::future::Future<Output = Result<DrawerStatus, RpcError>> + Send;
    /// A session's harness drawer: whether it exists, where it is, and whether it is shown and focused.
    fn drawer_status(
        &self,
        params: DrawerRequest,
    ) -> impl ::core::future::Future<Output = Result<DrawerStatus, RpcError>> + Send;
    /// Start an agent session: a harness process of the daemon, bound to a grant within the caller's.
    fn agent_sessions_create(
        &self,
        params: AgentSessionCreate,
    ) -> impl ::core::future::Future<Output = Result<AgentSession, RpcError>> + Send;
    /// Send a prompt; events follow on agent.sessions.events. A detached session is resumed first.
    fn agent_sessions_send(
        &self,
        params: AgentSessionSend,
    ) -> impl ::core::future::Future<Output = Result<AgentSession, RpcError>> + Send;
    /// A session's normalised events from its transcript, and with follow every later one as it happens.
    fn agent_sessions_events(
        &self,
        params: AgentSessionEventsQuery,
    ) -> impl ::core::future::Future<Output = Result<AgentSessionEvents, RpcError>> + Send;
    /// Stop the running turn; it ends with stop reason cancelled.
    fn agent_sessions_cancel(
        &self,
        params: AgentSessionRef,
    ) -> impl ::core::future::Future<Output = Result<AgentSession, RpcError>> + Send;
    /// Allow what a pending approval request asks.
    fn agent_sessions_approve(
        &self,
        params: AgentSessionAnswer,
    ) -> impl ::core::future::Future<Output = Result<AgentSession, RpcError>> + Send;
    /// Refuse what a pending approval request asks.
    fn agent_sessions_deny(
        &self,
        params: AgentSessionAnswer,
    ) -> impl ::core::future::Future<Output = Result<AgentSession, RpcError>> + Send;
    /// Sessions this caller may see, open and closed, from the state directory.
    fn agent_sessions_list(
        &self,
        params: Empty,
    ) -> impl ::core::future::Future<Output = Result<AgentSessionList, RpcError>> + Send;
    /// Start a detached session's harness again on the harness's own session.
    fn agent_sessions_resume(
        &self,
        params: AgentSessionRef,
    ) -> impl ::core::future::Future<Output = Result<AgentSession, RpcError>> + Send;
    /// End the harness process and close the session; its transcript stays.
    fn agent_sessions_close(
        &self,
        params: AgentSessionRef,
    ) -> impl ::core::future::Future<Output = Result<AgentSession, RpcError>> + Send;
    /// A registered app host publishes its current view for its pane; only the newest is kept.
    fn apps_publish(
        &self,
        params: AppViewPublish,
    ) -> impl ::core::future::Future<Output = Result<Empty, RpcError>> + Send;
    /// The view an app pane's host published last, waiting for a newer one (owner only).
    fn apps_view(
        &self,
        params: AppViewQuery,
    ) -> impl ::core::future::Future<Output = Result<AppView, RpcError>> + Send;
    /// Send a key to an app pane's host; it arrives as an `apps.input` event on the host's connection (owner only).
    fn apps_input(
        &self,
        params: AppInput,
    ) -> impl ::core::future::Future<Output = Result<Empty, RpcError>> + Send;
}

